// session ping
export const ping = {
  init(...args) {
    if (args.length !== 0) return { error: { message: "session ping: init requires 0 nat arguments" } };
    return muro__sess.init("ping", args);
  },
  send(state, value) { return muro__sess.step("ping", "send", state, value); },
  recv(state, value) { return muro__sess.step("ping", "recv", state, value); },
  done(state) { return muro__sess.done("ping", state); },
  expected(state) { return muro__sess.expected("ping", state); },
  check_trace(trace, opts) {
    if (!Array.isArray(trace)) return { error: { message: "session ping: check_trace requires a list" } };
    const complete = !!(opts && opts.complete === true);
    return muro__sess.trace("ping", [], trace, complete);
  }
};

